from dataclasses import dataclass, field

from .saj_slots import CHARGE, DISCHARGE, SAJ_SLOTS, SajSlot, Schedule

DAILY = 127                       # day mask: every day of the week
MODE_SELF_CONSUMPTION, MODE_TIME_OF_USE = 0, 1
GRID_FOLLOW_SLOT = 7              # the discharge slot the grid-follow owns


def entity_names(prefix: str = "saj") -> dict[str, str]:
    """The default entity id per key, after battery-api's ModbusEntityDiscovery (slot 1 reads without a number, the others with)."""
    names = {"app_mode": f"sensor.{prefix}_app_mode", "app_mode_input": f"number.{prefix}_app_mode_input",
             "charge_enable_input": f"number.{prefix}_charge_time_enable_input",
             "discharge_enable_input": f"number.{prefix}_discharge_time_enable_input"}
    for kind in (CHARGE, DISCHARGE):
        for n in range(1, SAJ_SLOTS + 1):
            write = f"{prefix}_{kind}{n}"
            names[f"{kind}{n}_start_input"] = f"text.{write}_start_time_time"
            names[f"{kind}{n}_end_input"] = f"text.{write}_end_time_time"
            names[f"{kind}{n}_power_input"] = f"number.{write}_power_percent_input"
            names[f"{kind}{n}_mask_input"] = f"number.{write}_day_mask_input"
    return names


