def _slot_input(slot: SajSlot) -> SlotInput:
    """A built slot as its input entities."""
    return SlotInput(slot.start, slot.end, slot.power_pct, DAILY)


def _mask(slots: tuple[SlotInput, ...]) -> int:
    """Enable bit mask of the slots that are in use (bit 0 = slot 1)."""
    return sum(1 << i for i, s in enumerate(slots) if s.day_mask)


def wanted_inputs(schedule: Schedule, grid_follow: SajSlot | None = None) -> InverterInputs:
    """The inputs for a schedule: sales in discharge slots 1 to 6, the grid-follow slot in 7, unused slots empty."""
    charge = tuple(_slot_input(s) for s in schedule.charge[:SAJ_SLOTS])
    charge += (EMPTY,) * (SAJ_SLOTS - len(charge))
    sales = tuple(_slot_input(s) for s in schedule.discharge[:GRID_FOLLOW_SLOT - 1])
    sales += (EMPTY,) * (GRID_FOLLOW_SLOT - 1 - len(sales))
    discharge = sales + (_slot_input(grid_follow) if grid_follow and grid_follow.power_pct > 0 else EMPTY,)
    any_slot = any(s.day_mask for s in charge + discharge)
    return InverterInputs(charge, discharge, _mask(charge), _mask(discharge), MODE_TIME_OF_USE if any_slot else MODE_SELF_CONSUMPTION)


def _slot_writes(kind: str, n: int, have: SlotInput, want: SlotInput, names: dict[str, str]) -> list[Write]:
    """The writes for one slot, only the fields that differ, in battery-api's order."""
    out = []
    if have.start != want.start:
        out.append(Write("text", names[f"{kind}{n}_start_input"], want.start))
    if have.end != want.end:
        out.append(Write("text", names[f"{kind}{n}_end_input"], want.end))
    if have.power_pct != want.power_pct:
        out.append(Write("number", names[f"{kind}{n}_power_input"], want.power_pct))
    if have.day_mask != want.day_mask:
        out.append(Write("number", names[f"{kind}{n}_mask_input"], want.day_mask))
    return out


def plan_writes(have: InverterInputs, want: InverterInputs, names: dict[str, str]) -> WritePlan:
    """The ordered writes from `have` to `want`: slot fields, then masks, then the mode. Idempotent: equal states give no writes."""
    writes: list[Write] = []
